root=Path(__file__).resolve().parent
P={'ink':'#2B201B','paper':'#EEE8DE','wine':'#582C3A','honey':'#D8A765','rust':'#A56841','fog':'#C8B9A6','light':'#FAF4E8'}
# vector collateral in physical dimensions, with 3mm provisional bleed
forms=[('ad-a5',154,216,'wine-room','A5 MAGAZINE / 148 x 210 mm','Light, after hours.'),('postcard-a6',154,111,'sun-room','A6 CARD / 148 x 105 mm','An hour worth staying for.'),('insert-a6',111,154,'hand-detail','A6 INSERT / 105 x 148 mm','A study in light and material.'),('sell-sheet-a4',216,303,'collection','A4 SELL SHEET / 210 x 297 mm','One silhouette. Three atmospheres.')]
for name,w,h,im,small,big in forms:
 data_uri='data:image/jpeg;base64,'+base64.b64encode((root/'images'/f'{im}.jpg').read_bytes()).decode('ascii')
 txt=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}mm" height="{h}mm" viewBox="0 0 {w} {h}" role="img" aria-label="BRUME conceptual print artwork: {big}"><rect width="{w}" height="{h}" fill="{P['paper']}"/><image href="{data_uri}" x="0" y="0" width="{w}" height="{h*.72}" preserveAspectRatio="xMidYMid slice"/><rect x="0" y="{h*.72}" width="{w}" height="{h*.28}" fill="{P['paper']}"/><text x="9" y="{h*.795}" font-family="Georgia,serif" font-size="{6.5 if w<200 else 9}" fill="{P['ink']}" letter-spacing="1.3">BRUME</text><text x="9" y="{h*.87}" font-family="Georgia,serif" font-size="{6.7 if w<200 else 9}" fill="{P['ink']}">{escape(big)}</text><text x="9" y="{h*.953}" font-family="Arial, sans-serif" font-size="3.4" fill="{P['wine']}">{escape(small)}</text></svg>'''
 (root/'print/svg'/f'{name}.svg').write_text(txt)

styles='''@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=EB+Garamond:ital,wght@0,400;0,500;1,400&display=swap');
:root{--ink:#2B201B;--paper:#EEE8DE;--wine:#582C3A;--honey:#D8A765;--rust:#A56841;--fog:#C8B9A6;--light:#FAF4E8;--rule:#C9BFB3;--sans:'DM Sans',Arial,sans-serif;--serif:'EB Garamond',Georgia,serif}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:25px}body{margin:0;background:var(--paper);color:var(--ink);font:400 16px/1.65 var(--sans)}h1,h2,h3,h4,p,figure{margin:0}h1,h2,h3{font-family:var(--serif);font-weight:400;line-height:1.04}p+p{margin-top:14px}a{color:inherit}img{display:block;width:100%;height:auto}.wrap{width:min(1270px,90%);margin:auto}.skip{position:absolute;top:-150px;left:16px;background:var(--honey);padding:12px;z-index:300}.skip:focus{top:12px}:focus-visible{outline:3px solid var(--rust)!important;outline-offset:4px}.cap,.eyebrow,.tag,.kicker{font:600 10px/1.65 var(--sans);letter-spacing:.14em;text-transform:uppercase}.nav{display:flex;align-items:center;justify-content:space-between;gap:23px;padding-block:22px;border-bottom:1px solid var(--rule)}.nav a{text-decoration:none}.nav strong{font:400 28px var(--serif);letter-spacing:.25em}.nav nav{display:flex;gap:27px;font-size:12px}.nav a:hover{text-decoration:underline;text-underline-offset:5px}.back{font-size:12px}.mast{background:var(--ink);color:var(--paper);padding:35px 0 65px}.mast .cap{color:var(--honey)}.mast h1{font-size:clamp(58px,8vw,133px);font-weight:400;letter-spacing:-.045em;line-height:.86;margin:42px 0 38px}.mast h1 i{font-weight:400}.mast .hero-grid{display:grid;grid-template-columns:1.3fr .7fr;gap:25px;align-items:end}.mast-photo{min-height:570px;width:100%;height:65vh;max-height:740px;object-fit:cover;object-position:center}.mast-copy{max-width:40ch;padding:30px 15px 15px}.mast-copy p{font-size:21px;font-family:var(--serif);line-height:1.35}.mast-copy a{display:inline-block;margin-top:22px;font-size:13px;border-bottom:1px solid var(--honey);text-decoration:none;padding-bottom:5px}.mast-footer{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:20px;color:#c6bbaf;font-size:10px;text-transform:uppercase;letter-spacing:.1em}.section{padding:100px 0}.section.alt{background:#D5C8B7}.section.dark{background:var(--ink);color:var(--light)}.section.wine{background:var(--wine);color:var(--light)}.section.kraft{background:#E6DCD0}.chapter{display:grid;grid-template-columns:.7fr 1.3fr;gap:10%;border-top:1px solid currentColor;padding-top:19px;margin-bottom:65px}.chapter .eyebrow{opacity:.7}.chapter h2{font-size:clamp(43px,5.2vw,80px);letter-spacing:-.04em;max-width:13ch}.chapter h2 em{color:var(--rust)}.chapter p{max-width:58ch}.chapter p.lead{font-family:var(--serif);font-size:clamp(24px,2.2vw,32px);line-height:1.26;margin-bottom:22px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.feature-photo{height:600px;object-fit:cover}.pair-text{display:flex;flex-direction:column;justify-content:space-between;padding:38px;background:#F4EEE5}.pair-text h3{font-size:48px;max-width:12ch}.pair-text p{max-width:37ch}.stat-strip{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid var(--rule);margin-top:45px}.stat-strip div{padding:23px;border-right:1px solid var(--rule)}.stat-strip div:last-child{border-right:0}.stat-strip strong{display:block;font-size:19px;font-weight:500;margin-top:11px}.social-gallery figure{min-width:0}.social-gallery figure img{aspect-ratio:4/5;object-fit:cover}.social-gallery .story img{aspect-ratio:9/16}.social-gallery figcaption{display:flex;justify-content:space-between;gap:12px;margin-top:10px;font:600 10px var(--sans);text-transform:uppercase;letter-spacing:.08em}.social-gallery a{text-decoration:none}.social-gallery img{transition:filter .2s}.social-gallery a:hover img{filter:brightness(.93)}.spacing{margin-top:65px}.minihead{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:22px}.minihead h3{font-size:40px}.minihead p{max-width:40ch;font-size:13px}.email-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.email-card{background:var(--paper);padding:13px;color:var(--ink)}.email-scroll{height:480px;overflow:hidden;background:white;border:1px solid #cec3b8}.email-scroll iframe{width:600px;height:1350px;transform:scale(.46);transform-origin:top left;border:0;pointer-events:none}.email-card h3{font-size:27px;margin:13px 0 8px}.email-card p{font-size:13px}.email-card a{font-size:12px;text-decoration:underline;text-underline-offset:4px}.brume-cta{display:inline-block;border:1px solid currentColor;padding:11px 17px;text-decoration:none;font-size:13px;margin-top:22px}.brume-cta:hover{background:var(--honey);color:var(--ink)}.print-gallery img{aspect-ratio:106/156;object-fit:contain;background:#dfd5cb;padding:18px}.print-gallery.wide img{aspect-ratio:154/216}.print-gallery figcaption{font:600 11px var(--sans);margin-top:10px}.spec{border-collapse:collapse;width:100%;font-size:13px}.spec td,.spec th{padding:15px 13px;border-bottom:1px solid var(--rule);text-align:left}.spec th{font-size:11px;letter-spacing:.08em}.story-panel{background:var(--light);color:var(--ink);padding:28px}.story-panel h3{font-size:39px}.story-panel p{font-size:14px;margin-top:20px}.research-card{padding:25px;border-top:1px solid}.research-card strong{font:500 26px var(--serif)}.research-card p{font-size:13px;margin-top:15px}.research-card a{font-size:12px;word-wrap:break-word}.foot{padding:76px 0;background:var(--ink);color:var(--paper)}.foot h2{font-size:75px}.foot a{display:block;margin:8px 0}.foot .grid2{align-items:end}.note{font-size:13px;color:#67544D;margin-top:20px}.case-meta{display:flex;flex-wrap:wrap;gap:20px;margin-top:30px}.case-meta span{font-size:11px;letter-spacing:.1em;text-transform:uppercase}.mockup-scene{display:flex;align-items:center;justify-content:center;gap:5%;padding:55px 20px;background:#d2bcaa}.mockup{padding:10px;background:#f9f4ed;box-shadow:12px 16px 25px #442e255c;transform:rotate(-3deg);width:25%}.mockup:nth-child(2){transform:rotate(4deg) translateY(-15px)}.mockup img{aspect-ratio:106/156;padding:0}.mockup-caption{font:600 11px var(--sans);margin-top:24px}
@media(max-width:980px){.mast .hero-grid{grid-template-columns:1fr}.mast-photo{height:58vh;max-height:680px}.mast-copy{max-width:60ch}.chapter{grid-template-columns:1fr;gap:25px}.grid4{grid-template-columns:repeat(2,1fr)}.email-grid{grid-template-columns:1fr 1fr}.email-card:last-child{grid-column:span 2}}
@media(max-width:660px){.nav{flex-wrap:wrap}.nav nav{width:100%;justify-content:space-between;border-top:1px solid var(--rule);padding-top:10px;font-size:11px;gap:12px}.back{font-size:11px}.mast{padding:20px 0 40px}.mast h1{font-size:62px;margin:30px 0}.mast-photo{height:480px;min-height:0}.mast-copy{padding:20px 0}.mast-copy p{font-size:20px}.section{padding:65px 0}.chapter{margin-bottom:37px}.chapter h2{font-size:48px}.grid2,.grid3,.email-grid{grid-template-columns:1fr}.grid4{grid-template-columns:repeat(2,1fr)}.email-card:last-child{grid-column:auto}.feature-photo{height:auto}.pair-text{padding:25px;min-height:260px}.stat-strip{grid-template-columns:1fr 1fr}.stat-strip div{border-bottom:1px solid var(--rule)}.minihead{display:block}.minihead p{margin-top:10px}.foot h2{font-size:56px}.mockup-scene{padding:30px 10px}.mockup{width:30%;padding:4px;box-shadow:5px 8px 12px #442e2544}}
@media(max-width:390px){.grid4{grid-template-columns:1fr}.mast h1{font-size:55px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
'''
(root/'brume.css').write_text(styles)
nav='''<a href="../index.html#work" class="back">← Jocelyn Martinez / Selected work</a><a href="index.html"><strong>BRUME</strong></a><nav aria-label="Project navigation"><a href="index.html#campaign">Campaign</a><a href="index.html#social">Social</a><a href="index.html#email">Email</a><a href="production.html">Print</a><a href="research.html">Research</a></nav>'''
def begin(title,description):return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(description)}"><title>{escape(title)} — Jocelyn Martinez</title><link rel="icon" href="../assets/jm-mark.svg" type="image/svg+xml"><link rel="stylesheet" href="brume.css"></head><body><a class="skip" href="#main">Skip to main content</a><header class="nav wrap">{nav}</header><main id="main">'''
footer='''</main><footer class="foot"><div class="wrap grid2"><div><span class="cap">BRUME / ART DIRECTION &amp; DESIGN</span><h2>An hour<br>to remember.</h2></div><div><p>Self-directed, AI-assisted fictional lighting collection. Campaign imagery is generated illustration, not commercial product photography. There were no manufactured lights, real client outcomes, electrical certificates or physical packaging approvals.</p><a href="production.html">Print and packaging study ↗</a><a href="research.html">Visual references and process ↗</a><a href="../index.html#work">Return to selected work ↗</a></div></div></footer></body></html>'''

social=[('01-launch','Launch'),('02-maroon','Plum'),('03-cream','Ivory'),('04-amber','Amber'),('05-collection','The trio')]+[(f'carousel-{i:02}',f'Carousel / {i:02}') for i in range(1,7)]+[(f'story-{i:02}',f'Story / {i:02}') for i in range(1,4)]+[('landscape-01','Professional landscape')]
def social_fig(x):
 f,n=x;return f'''<figure><a href="social/{f}.svg" title="View editable SVG for {escape(n)}"><img src="social/{f}.svg?v=20261024-embedded" alt="BRUME photographic campaign composition, {escape(n)}" loading="lazy"></a><figcaption><span>{escape(n)}</span><a href="social/{f}.svg">SVG source ↗</a></figcaption></figure>'''

email=[('01-introduction','The launch'),('02-material','The collection'),('03-detail','The details')]
def email_card(e):
 f,n=e;return f'''<article class="email-card"><div class="email-scroll"><iframe loading="lazy" tabindex="-1" title="BRUME email {escape(n)}" src="email/{f}.html"></iframe></div><h3>{escape(n)}</h3><p>Live-text, table-first sample email with a linked photographic hero, Outlook-width fallback, clear call to action and a plain-text alternative.</p><p><a href="email/{f}.html" target="_blank" rel="noopener">View full email ↗</a> · <a href="email/{f}.txt">Plain-text version ↗</a></p></article>'''

site=begin('BRUME / Photographic campaign, email and art direction','Photography-led commercial campaign study with social masters and three HTML emails')+f'''
<section class="mast" id="campaign"><div class="wrap"><div class="cap">01 / CREATIVE DIRECTION · SELF-INITIATED · 2026</div><h1>Light,<br><i>after hours.</i></h1><div class="hero-grid"><img class="mast-photo" src="images/wine-room.jpg" alt="Illustrative wine-colored ribbed glass lamp glowing against a textured evening interior"><div class="mast-copy"><p>A lamp can change a room. A carefully directed photograph can make us feel that change before a word is read.</p><p style="font-family:var(--sans);font-size:14px;margin-top:22px">BRUME is a fictional sculptural lighting studio built as a complete launch study: photographic campaign, social assets, email marketing, product identity and print-artwork specifications.</p><a href="#social">Explore the campaign ↓</a></div></div><div class="mast-footer"><span>CAMPAIGN / PHOTOGRAPHY / TYPE</span><span>15 ARTWORK MASTERS</span><span>3 RESPONSIVE EMAILS</span><span>3 COLOR STUDIES</span></div></div></section>
<section class="section" id="brief"><div class="wrap"><div class="chapter"><span class="eyebrow">01 / THE COMMERCIAL QUESTION</span><div><h2>A better feeling <em>without a louder ad.</em></h2><p class="lead">What if a lighting launch made space for the object, not just its logo?</p><p>Most lighting products are evaluated not just as objects, but as atmosphere. This concept uses setting, material and directional light to show one sculptural silhouette in three moods—Plum, Ivory, and Amber.</p><p>Audience and business objectives are hypotheses, not research findings. The target is design-aware homeware buyers who value material expression. The central communication task is simple: make each color edition recognizable and communicate that the collection belongs together.</p></div></div><div class="stat-strip"><div><span class="eyebrow">OBJECT</span><strong>Ribbed glass table light</strong></div><div><span class="eyebrow">VISUAL PRINCIPLE</span><strong>Photography before typography</strong></div><div><span class="eyebrow">CAMPAIGN</span><strong>Social + email + print</strong></div><div><span class="eyebrow">STATUS</span><strong>Concept / unmanufactured</strong></div></div></div></section>
<section class="section alt" id="world"><div class="wrap"><div class="chapter"><span class="eyebrow">02 / PHOTOGRAPHIC DIRECTION</span><div><h2>Not a symbol.<br><em>A material.</em></h2><p class="lead">Every composition begins with how the glass catches light.</p><p>Warm reflected highlights, tactile stone, ribbed surfaces and small domestic gestures carry the brand. Typography is intentionally quieter than in my other portfolio projects. The continuity comes from a precise product silhouette and luminous material, not a repeated headline template.</p></div></div><div class="grid2"><img class="feature-photo" src="images/collection.jpg" alt="Illustrative studio photograph of three sculptural colored glass lamps arranged on architectural blocks" loading="lazy"><div class="pair-text"><span class="eyebrow">COLOR STUDY / 03</span><h3>One form.<br>Three atmospheres.</h3><p>Plum after dark. Ivory in daylight. Amber in the moment between. The collection uses variations in environment and light to communicate product identity.</p><a class="brume-cta" href="images/collection.jpg">View photographic master ↗</a></div><img class="feature-photo" src="images/sun-room.jpg" alt="Illustrative ivory lamp in a sunlit stone interior" loading="lazy"><img class="feature-photo" src="images/hand-detail.jpg" alt="Illustrative amber-colored lamp detail with a hand adjusting the object" loading="lazy"></div><p class="note">All lamp imagery is AI-generated, showing an imagined object and proposed photo direction. No real photography session or physical product is claimed.</p></div></section>
<section class="section" id="social"><div class="wrap"><div class="chapter"><span class="eyebrow">03 / SOCIAL CAMPAIGN</span><div><h2>Same object.<br><em>Different pace.</em></h2><p class="lead">A complete collection of editable artwork—designed to change the frame, not only the caption.</p><p>Five introductory and edition-focused posts, six carousel frames, three vertical story studies, and one landscape campaign composition. Each uses a different crop or editorial relationship; all share one recognizable photographic world.</p></div></div><div class="minihead"><h3>Feed / five introductions</h3><p>Full-height photographic panels, material studies, framed details and deliberate white space.</p></div><div class="social-gallery grid3">{''.join(social_fig(x) for x in social[:5])}</div><div class="spacing minihead"><h3>Editorial carousel / six frames</h3><p>Six different messages, moving from object to material and evening atmosphere.</p></div><div class="social-gallery grid3">{''.join(social_fig(x) for x in social[5:11])}</div><div class="spacing minihead"><h3>Stories &amp; landscape</h3><p>Each story is composed for a vertical format; the landscape ad is recomposed for a wider viewing distance.</p></div><div class="social-gallery grid3">{''.join(social_fig(x) for x in social[11:14])}</div><div class="social-gallery grid2 spacing">{social_fig(social[-1])}</div><p class="note">Each asset opens its editable SVG source, which links to original generated imagery included in this package. Flattened PNG renditions are also included. Platform safe-zone validation remains outstanding.</p></div></section>
<section class="section dark" id="email"><div class="wrap"><div class="chapter"><span class="eyebrow">04 / DIGITAL CAMPAIGNS</span><div><h2>From inbox<br><em>to image.</em></h2><p class="lead">Three emails where the image works first, and the message still works without it.</p><p>The launch email uses a nocturnal hero, the product-study email shows the three objects, and the final note zooms into material detail. All key messaging and calls to action remain live HTML. The mailing URLs and unsubscribe systems are deliberately nonfunctional examples.</p></div></div><div class="email-grid">{''.join(email_card(x) for x in email)}</div><p class="note" style="color:#cabeb2">Email previews are approximate web renderings, not claims of verified Gmail, Outlook, Apple Mail or dark-mode inbox rendering.</p></div></section>
<section class="section kraft"><div class="wrap"><div class="chapter"><span class="eyebrow">05 / ART DIRECTION TO DELIVERY</span><div><h2>Where the<br><em>idea travels.</em></h2><p class="lead">A campaign is a system of changing decisions, not one master image.</p><p>Social sources use vector text and linked images. Email templates contain their own table layout and live message. Product color editions carry independent artwork identifiers. The print companion project documents actual intended dimensions and a fictional revision log without presenting concept artwork as press-approved.</p><a class="brume-cta" href="production.html">Explore the print &amp; packaging case study ↗</a></div></div></div></section>
'''+footer
(root/'index.html').write_text(site)

production=begin('BRUME / print and packaging design','Technical companion case study for BRUME label family, advertising collateral and revisions')+'''
<section class="mast"><div class="wrap"><span class="cap">02 / PRINT &amp; PACKAGING / CONCEPT ARTWORK</span><h1>Made to<br><i>be held.</i></h1><div class="hero-grid"><img class="mast-photo" src="images/collection.jpg" alt="Three imaginary ribbed glass lamps photographed together on stone plinths"><div class="mast-copy"><p>From the careful edge of a label to the scale of a magazine page, a graphic system needs to hold up beyond a screen.</p><p style="font:14px/1.7 var(--sans);margin-top:20px">Three dimensional product-label masters. A print advertising family. A transparent revision archive. Real print geometry—with vendor-dependent production work clearly marked as pending.</p><a href="#labels">See flat master artwork ↓</a></div></div><div class="mast-footer"><span>3 LABEL VARIANTS</span><span>4 PRINT COLLATERAL FORMATS</span><span>2 ARCHIVED REVISIONS</span><span>3 MM PROVISIONAL BLEED</span></div></div></section>
<section class="section" id="labels"><div class="wrap"><div class="chapter"><span class="eyebrow">01 / IDENTITY IN PRINT</span><div><h2>What stays.<br><em>What shifts.</em></h2><p class="lead">Three edition labels, one balanced architecture.</p><p>The label family reserves consistent zones for a wordmark, editorial color field, edition name, artwork identifier and limited descriptive text. Material/color is the expressive distinction; the information system stays stable. These are concept fronts, not a complete regulated electrical-product packaging system.</p></div></div><div class="grid3 print-gallery">'''+''.join(f'<figure><a href="print/svg/brume-label-{x}-r03.svg"><img loading="lazy" src="print/svg/brume-label-{x}-r03.svg?v=20261024-embedded" alt="Flat vector master of BRUME {x} label"></a><figcaption>{x.upper()} / EDITION MASTER / SVG SOURCE</figcaption></figure>' for x in ['plum','ivory','amber'])+'''</div><div class="spacing minihead"><h3>Applied context / illustrative</h3><p>These are presentation studies, not die-tested or physically manufactured packages.</p></div><div class="mockup-scene">'''+''.join(f'<div class="mockup"><img src="print/svg/brume-label-{x}-r03.svg?v=20261024-embedded" alt="Illustrative sleeve treatment for BRUME {x}"></div>' for x in ['plum','ivory','amber'])+'''</div></div></section>
<section class="section alt" id="collateral"><div class="wrap"><div class="chapter"><span class="eyebrow">02 / PRINT CAMPAIGN</span><div><h2>One campaign.<br><em>Four formats.</em></h2><p class="lead">The photography travels from emotional brand advertising to practical product communication.</p><p>An A5 magazine page, A6 promotional postcard, A6 concept insert and A4 product sheet. The same material direction adapts to reading distance and information density rather than copying a social post into a paper rectangle.</p></div></div><div class="grid2 print-gallery wide">'''+''.join(f'<figure><a href="print/svg/{x}.svg"><img src="print/svg/{x}.svg?v=20261024-embedded" alt="BRUME editable print design for {n}" loading="lazy"></a><figcaption>{n.upper()} / EDITABLE SVG ↗</figcaption></figure>' for x,n in [('ad-a5','A5 magazine advertising'),('postcard-a6','A6 postcard'),('insert-a6','A6 concept insert'),('sell-sheet-a4','A4 product sheet')])+'''</div></div></section>
<section class="section" id="revisions"><div class="wrap"><div class="chapter"><span class="eyebrow">03 / PRODUCTION CONTROL</span><div><h2>Small corrections.<br><em>Visible history.</em></h2><p class="lead">Labels change. Their history should not disappear.</p><p>The fictional revision example follows the PLUM edition from a generic color name to an explicit glass description, then to a revised studio-edition label. Prior files stay in the archive; no production or legal approval is invented.</p></div></div><div class="grid3 print-gallery">'''+''.join(f'<figure><a href="print/archive/brume-label-plum-r0{i}.svg"><img src="print/archive/brume-label-plum-r0{i}.svg" alt="Archived version {i} label artwork"></a><figcaption>ARCHIVE / R0{i}</figcaption></figure>' for i in (1,2))+'''<figure><a href="print/svg/brume-label-plum-r03.svg"><img src="print/svg/brume-label-plum-r03.svg?v=20261024-embedded" alt="Current conceptual Plum label, revision three"></a><figcaption>CONCEPT-CURRENT / R03</figcaption></figure></div></div></section>
<section class="section kraft" id="preflight"><div class="wrap"><div class="chapter"><span class="eyebrow">04 / SOURCE &amp; PREFLIGHT</span><div><h2>A proof is<br><em>not a promise.</em></h2><p class="lead">Explicit dimensions and PDF boxes are useful; a real printer still must approve the output.</p><p>Each current SVG defines page dimensions in millimeters with 3 mm provisional bleed. The downloadable PDF specimens have programmatically set TrimBox/BleedBox and embedded fonts. But they are not PDF/X-certified, color-managed to an actual print condition, safety-compliant, or validated against a manufacturer-issued label die.</p></div></div><table class="spec"><thead><tr><th>Piece</th><th>Planned trim</th><th>Source including 3 mm bleed</th><th>Unverified production details</th></tr></thead><tbody><tr><td>Edition label</td><td>100 × 150 mm</td><td>106 × 156 mm</td><td>Actual die, adhesive, substrate, electrical details</td></tr><tr><td>Magazine ad</td><td>148 × 210 mm</td><td>154 × 216 mm</td><td>Magazine output intent, ink and page rules</td></tr><tr><td>Promotional postcard</td><td>148 × 105 mm</td><td>154 × 111 mm</td><td>Back-of-card layout, paper, postage rules</td></tr><tr><td>Concept insert</td><td>105 × 148 mm</td><td>111 × 154 mm</td><td>Safety copy, usage guidance, product testing</td></tr><tr><td>Product sell sheet</td><td>210 × 297 mm</td><td>216 × 303 mm</td><td>Real product pricing, specifications and claims</td></tr></tbody></table><div class="story-panel"><h3>Before a real print run</h3><p>Obtain verified CAD/dielines and manufacturing specifications. Supply compliant electrical ratings, safety instructions and warranty statements. Preflight against the printer's ICC profile and PDF/X requirements; proof actual colors, image effective resolution, legibility, barcodes and overprint. Obtain a physical sample and signed authorization. None of these external validations are claimed here.</p><a class="brume-cta" href="print/BRUME-ALL-PROOFS.pdf">Download combined technical specimen PDF ↗</a></div></div></section>'''+footer
(root/'production.html').write_text(production)

